// @generated by:gauntlet run:godseye-local-backend
import { randomUUID } from "node:crypto";
import { readFile, truncate } from "node:fs/promises";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { FileView } from "../packages/app-backend/src/index.js";
import { appendFile, committedFile, fileJson, initiateFile } from "./backend-file-fixture.js";
import { type BackendFixture, backendFixture } from "./backend-fixture.js";

/** Fail the chosen real database transaction AFTER its work but BEFORE commit. */
function failCommit(fixture: BackendFixture, number: number) {
  const original = fixture.store.transaction.bind(fixture.store);
  let count = 0;
  fixture.store.transaction = (work) =>
    original(async (tx) => {
      const result = await work(tx);
      if (++count === number) throw new Error("Synthetic fixture transaction interruption");
      return result;
    });
  return () => {
    fixture.store.transaction = original;
  };
}

describe("durable file intents across physical-effect acknowledgement failure", () => {
  let fixture: BackendFixture | undefined;
  afterEach(async () => fixture?.close());
  async function setup() {
    fixture = await backendFixture({ limits: { objectBytes: 8, storageBytes: 8 } });
    return { fixture, cookie: (await fixture.register()).cookie };
  }

  it("T-AC-56 retains uncertain written bytes and reservation across restart, then reconciles the exact chunk", async () => {
    const { fixture, cookie } = await setup();
    const bytes = new TextEncoder().encode("12345678");
    const initial = await initiateFile(fixture, cookie, bytes);
    const restore = failCommit(fixture, 2);
    const interrupted = await appendFile(fixture, cookie, initial, bytes);
    restore();
    expect(interrupted.status).toBe(500);
    expect(await readFile(join(fixture.filesRoot, initial.id))).toEqual(Buffer.from(bytes));
    await fixture.restart();
    const pending = FileView.parse(
      await (await fixture.request(`/files/${initial.id}`, { headers: { cookie } })).json(),
    );
    expect(pending).toMatchObject({ offset: 0, status: "uploading", revision: initial.revision });
    const overcommit = await fileJson(fixture, cookie, "/files", {
      name: "overcommit",
      contentType: "text/plain",
      size: 1,
    });
    expect(overcommit.status).toBe(409);
    const reconciled = await appendFile(fixture, cookie, pending, bytes);
    expect(reconciled.status).toBe(200);
    const progress = FileView.parse(await reconciled.json());
    expect(progress.offset).toBe(bytes.length);
    expect(await readFile(join(fixture.filesRoot, initial.id))).toEqual(Buffer.from(bytes));
    expect(
      (
        await fileJson(fixture, cookie, `/files/${initial.id}/complete`, {
          expectedRevision: progress.revision,
        })
      ).status,
    ).toBe(200);
  });

  it("T-AC-56 rejects a different chunk while a prior physical write remains uncertain", async () => {
    const { fixture, cookie } = await setup();
    const bytes = new TextEncoder().encode("12345678");
    const initial = await initiateFile(fixture, cookie, bytes);
    const restore = failCommit(fixture, 2);
    expect((await appendFile(fixture, cookie, initial, bytes)).status).toBe(500);
    restore();
    const conflict = await appendFile(
      fixture,
      cookie,
      initial,
      new TextEncoder().encode("87654321"),
    );
    expect(conflict.status).toBe(409);
    expect(await readFile(join(fixture.filesRoot, initial.id))).toEqual(Buffer.from(bytes));
    expect(
      (await fixture.request(`/files/${initial.id}/download`, { headers: { cookie } })).status,
    ).toBe(404);
  });

  it("T-AC-56 reconciles a crash-shortened pending chunk only when its retained prefix matches", async () => {
    const { fixture, cookie } = await setup();
    const bytes = new TextEncoder().encode("12345678");
    const initial = await initiateFile(fixture, cookie, bytes);
    const restore = failCommit(fixture, 2);
    expect((await appendFile(fixture, cookie, initial, bytes)).status).toBe(500);
    restore();
    await truncate(join(fixture.filesRoot, initial.id), 3);
    await fixture.restart();
    const resumed = await appendFile(fixture, cookie, initial, bytes);
    expect(resumed.status).toBe(200);
    expect(FileView.parse(await resumed.json()).offset).toBe(bytes.length);
    expect(await readFile(join(fixture.filesRoot, initial.id))).toEqual(Buffer.from(bytes));
  });

  it("T-AC-57 persists a tombstone before unlink and retains cleanup quota until exact replay settles", async () => {
    const { fixture, cookie } = await setup();
    const { file } = await committedFile(fixture, cookie, "12345678");
    const key = randomUUID();
    const restore = failCommit(fixture, 2);
    const remove = () =>
      fixture.request(`/files/${file.id}`, {
        method: "DELETE",
        headers: { cookie, "content-type": "application/json", "idempotency-key": key },
        body: JSON.stringify({ expectedRevision: file.revision }),
      });
    expect((await remove()).status).toBe(500);
    restore();
    await expect(readFile(join(fixture.filesRoot, file.id))).rejects.toMatchObject({
      code: "ENOENT",
    });
    await fixture.restart();
    expect(
      (await fixture.request(`/files/${file.id}/download`, { headers: { cookie } })).status,
    ).toBe(404);
    const input = { name: "replacement", contentType: "text/plain", size: 1 };
    expect((await fileJson(fixture, cookie, "/files", input)).status).toBe(409);
    expect((await remove()).status).toBe(200);
    expect((await fileJson(fixture, cookie, "/files", input)).status).toBe(201);
  });
});
